def hasMatch(s: str, p: str) -> bool:
    star_index = p.index('*')
    prefix = p[:star_index]
    suffix = p[star_index + 1:]

    # Check for all possible starting points in s for the prefix
    for i in range(len(s) - len(prefix) - len(suffix) + 2):
        if s[i:i + len(prefix)] == prefix:
            # Check if the remainder of s can end with the suffix
            if s[i + len(prefix):i + len(prefix) + len(suffix)].startswith(suffix):
                return True

    return False

