def largestInteger(nums: List[int], k: int) -> int:
    from collections import defaultdict

    count = defaultdict(int)
    n = len(nums)

    # Count appearances of each integer in all subarrays of size k
    for i in range(n - k + 1):
        appeared = set()
        for j in range(k):
            if nums[i + j] not in appeared:
                count[nums[i + j]] += 1
                appeared.add(nums[i + j])

    # Find the largest integer that appears in exactly one subarray
    largest_missing = -1
    for num, c in count.items():
        if c == 1:
            largest_missing = max(largest_missing, num)

    return largest_missing

