def longestSubsequence(nums: List[int]) -> int:
    n = len(nums)
    if n == 0:
        return 0

    dp = [1] * n
    max_length = 1

    for i in range(1, n):
        for j in range(i):
            if abs(nums[i] - nums[j]) >= (dp[j] - 1 if j > 0 else 0):
                dp[i] = max(dp[i], dp[j] + 1)
                max_length = max(max_length, dp[i])

    return max_length

def calculateScore(s: str) -> int:
    score = 0
    marked = [False] * len(s)
    mirror = lambda c: chr(ord('z') - (ord(c) - ord('a')))
    for i in range(len(s)):
        if marked[i]:
            continue
        for j in range(i - 1, -1, -1):
            if not marked[j] and s[j] == mirror(s[i]):
                marked[i] = marked[j] = True
                score += i - j
                break
    return score

