import heapq

def minMaxWeight(n: int, edges: List[List[int]], threshold: int) -> int:
    graph = {i: [] for i in range(n)}
    for u, v, w in edges:
        graph[u].append((v, w))  # use directed edges as provided

    def can_reach_node_zero(max_weight: int) -> bool:
        out_degree = [0] * n
        queue = []
        visited = [False] * n

        for v in range(n):
            for u, w in graph[v]:
                if w <= max_weight:
                    out_degree[v] += 1  

        for v in range(n):
            if out_degree[v] < threshold:
                heapq.heappush(queue, v)

        while queue:
            node = heapq.heappop(queue)
            if visited[node]:
                continue
            visited[node] = True
            for u, w in graph[node]:
                if not visited[u] and w <= max_weight:
                    out_degree[u] -= 1
                    if out_degree[u] < threshold:
                        heapq.heappush(queue, u)

        return visited[0]

    low, high = 1, 10**6
    result = -1
    while low <= high:
        mid = (low + high) // 2
        if can_reach_node_zero(mid):
            result = mid
            high = mid - 1
        else:
            low = mid + 1

    return result

