def minCost(n: int, cost: List[List[int]]) -> int:
    dp = [[0]*3 for _ in range(n)]
    for j in range(3):
        dp[0][j] = cost[0][j]
    for i in range(1, n):
        for j in range(3):
            dp[i][j] = cost[i][j] + min(dp[i-1][(j+1) % 3], dp[i-1][(j+2) % 3])
    min_cost = float('inf')
    # Handle equidistant house condition
    for j in range(3):
        min_cost = min(min_cost, dp[n-1][j] + (cost[0][j] if j == 0 else 0))
        min_cost = min(min_cost, dp[n-2][j])  # Last two have to be different if n is even
    return min_cost

from typing import List

def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    online_status = [True] * numberOfUsers
    event_list = []

    for event in events:
        event_type, timestamp, *args = event
        timestamp = int(timestamp)

        if event_type == 'OFFLINE':
            user_id = int(args[0])
            online_status[user_id] = False
            event_list.append((timestamp + 60, 'ONLINE', user_id))
        elif event_type == 'MESSAGE':
            mentions_string = args[0]
            event_list.append((timestamp, 'MESSAGE', mentions_string))

    event_list.sort()

    for time, event_type, data in event_list:
        if event_type == 'MESSAGE':
            mentions_string = data
            mentioned_users = set()
            if mentions_string == 'HERE':
                for user_id in range(numberOfUsers):
                    if online_status[user_id]:
                        mentioned_users.add(user_id)
            elif mentions_string == 'ALL':
                mentioned_users = set(range(numberOfUsers))
            else:
                for mention in mentions_string.split():
                    if mention.startswith('id'):
                        user_id = int(mention[2:])
                        mentioned_users.add(user_id)

            for user_id in mentioned_users:
                mentions[user_id] += 1
        elif event_type == 'ONLINE':
            user_id = data
            online_status[user_id] = True

    return mentions
